window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[46]={"id":"046","numero":46,"titre":"Médecine génomique","strategie":{"urgence":"\n<p><strong>Pas d'<span class=\"kw-alerte\">urgence</span> vitale propre au champ « médecine génomique ».</strong> Les urgences relèvent de la maladie sous-jacente identifiée par le séquençage (cardiopathie, cancer, maladie métabolique néonatale, etc.).</p>\n<ul>\n  <li><span class=\"kw-alerte\">Rendu d'un variant pathogène à risque vital</span> (ex. <span class=\"kw-etio\">mutation BRCA1/2</span>, <span class=\"kw-etio\">syndrome de Lynch</span>, <span class=\"kw-etio\">cardiomyopathie hypertrophique</span>) → orientation rapide vers la filière spécialisée pour <span class=\"kw-ttt\">mesures de prévention</span> et information de la parentèle.</li>\n  <li><span class=\"kw-alerte\">Découverte fortuite (incidentalome génomique)</span> d'un variant actionnable → discussion en <strong><span class=\"kw-def\">RCP</span> de <span class=\"kw-etio\">génétique</span> constitutionnelle</strong> avant rendu au patient.</li>\n</ul>","hospit":"\n<p><strong>Filière France Médecine Génomique 2025 (Plan FMG2025) :</strong></p>\n<ul>\n  <li>Prescription en <strong>consultation de <span class=\"kw-etio\">génétique</span></strong> par un <span class=\"kw-def\">médecin agréé</span> (généticien, oncogénéticien, ou médecin spécialiste formé).</li>\n  <li>Adressage vers une des deux <strong>plateformes nationales de séquençage très haut débit</strong> : <em>SeqOIA</em> (Île-de-France) ou <em>AURAGEN</em> (Auvergne-Rhône-Alpes).</li>\n  <li>Indications validées par <strong><span class=\"kw-def\">réunion de concertation pluridisciplinaire</span> (RCP)</strong> selon des préindications (PFMG) : maladies rares, cancers, échec de diagnostic.</li>\n  <li><strong>CRMR / FSMR</strong> (Centre de Référence / Filière de Santé Maladies Rares) coordonne le parcours.</li>\n  <li>Rendu en <strong>consultation dédiée</strong> par le prescripteur, accompagnement par un <span class=\"kw-def\">conseiller en génétique</span>.</li>\n</ul>","redflags":"\n<ul>\n  <li><span class=\"kw-alerte\">Test génétique réalisé sans consentement écrit signé</span> → faute professionnelle (loi de bioéthique).</li>\n  <li><span class=\"kw-alerte\">Rendu d'un résultat génétique par téléphone, courrier ou mail</span> → <span class=\"kw-ci\">proscrit</span> ; rendu obligatoire en <strong>consultation</strong>.</li>\n  <li><span class=\"kw-alerte\">Test génétique chez un mineur asymptomatique</span> pour une pathologie à révélation adulte sans PEC disponible → <span class=\"kw-ci\">contre-indiqué</span>.</li>\n  <li><span class=\"kw-alerte\">Variant de signification incertaine (VUS)</span> rendu comme « pathogène » → erreur d'interprétation, <span class=\"kw-ci\">jamais de</span> décision thérapeutique sur un VUS.</li>\n  <li><span class=\"kw-alerte\">Refus du patient d'informer la parentèle</span> à risque grave et accessible à une prévention → le médecin peut, avec accord du patient, informer indirectement les apparentés (procédure encadrée).</li>\n  <li><span class=\"kw-alerte\">Test génétique commandé en direct par le patient sur internet (DTC)</span> → non encadré, non remboursé, à confirmer en laboratoire agréé avant toute décision.</li>\n</ul>","principes":"\n<p><strong>Principes de prescription d'un test <span class=\"kw-etio\">génétique</span> constitutionnel :</strong></p>\n<ul>\n  <li><strong>Prescripteur autorisé</strong> : médecin ayant <span class=\"kw-def\">suivi</span> une formation à la <span class=\"kw-etio\">génétique</span> (décret 2013).</li>\n  <li><span class=\"kw-def\">Consentement écrit éclairé</span> obligatoire, daté et signé, après <strong>information préalable</strong> (objectifs, limites, conséquences familiales).</li>\n  <li><strong>Arbre généalogique sur <span class=\"kw-chiffre\">≥ 3 g</span>énérations</strong> systématique.</li>\n  <li><strong>Délai de réflexion</strong> entre consultation et prélèvement.</li>\n  <li><strong>Rendu en consultation</strong> par le prescripteur, jamais par téléphone ou courrier.</li>\n  <li><strong>Information de la parentèle</strong> : devoir du patient ; le médecin peut informer indirectement (loi de bioéthique 2011/2021).</li>\n  <li><strong>Examen du mineur</strong> : limité aux pathologies à expression pédiatrique avec PEC disponible.</li>\n  <li>Tests réalisés en <strong>laboratoires agréés</strong> (ABM — Agence de la Biomédecine).</li>\n</ul>\n<p><strong>Indications principales du séquençage haut débit (NGS) :</strong></p>\n<ul>\n  <li><strong>Diagnostic</strong> de maladie rare avec présomption <span class=\"kw-etio\">génétique</span> (déficience intellectuelle, dysmorphie, maladie métabolique, cardiomyopathie…).</li>\n  <li><strong>Oncogénétique constitutionnelle</strong> : prédisposition <span class=\"kw-etio\">héréditaire</span> au cancer (<span class=\"kw-etio\">BRCA1/2</span>, <span class=\"kw-etio\">Lynch</span>, <span class=\"kw-etio\">Li-Fraumeni</span>…).</li>\n  <li><strong>Oncologie somatique</strong> : tumeur — recherche de biomarqueurs de traitement ciblé.</li>\n  <li><strong>Pharmacogénétique</strong> : adaptation thérapeutique (<span class=\"kw-etio\">DPD</span>, <span class=\"kw-etio\">TPMT</span>, <span class=\"kw-etio\">CYP2C19</span>…).</li>\n  <li><strong>Diagnostic prénatal / préimplantatoire</strong> dans le cadre du CPDPN.</li>\n</ul>","suivi":"\n<p><strong>Après rendu du résultat :</strong></p>\n<ul>\n  <li><strong>Variant pathogène / probablement pathogène</strong> → <span class=\"kw-ttt\">PEC spécifique</span> de la pathologie + <strong>conseil <span class=\"kw-etio\">génétique</span> familial</strong> + <span class=\"kw-def\">dépistage</span> en cascade des apparentés.</li>\n  <li><strong>Variant de signification incertaine (VUS)</strong> → <strong>aucune décision thérapeutique</strong> ; <span class=\"kw-def\">réévaluation</span> périodique selon <span class=\"kw-clinique\">évolution</span> des connaissances.</li>\n  <li><strong>Résultat négatif</strong> → ne suffit pas à exclure une cause <span class=\"kw-etio\">génétique</span> (limites techniques) ; selon contexte, élargissement (exome, génome) ou <span class=\"kw-def\">réévaluation</span> à distance.</li>\n  <li><strong>Découverte secondaire / incidentalome</strong> → discussion <span class=\"kw-def\">RCP</span> avant rendu, choix du patient (recueilli au consentement initial) respecté.</li>\n  <li><span class=\"kw-ttt\">Soutien psychologique</span> proposé systématiquement.</li>\n  <li>Inscription dans <strong>filière nationale de maladies rares</strong> (FSMR / CRMR) pour le <span class=\"kw-def\">suivi</span> multidisciplinaire.</li>\n  <li>PEC à <span class=\"kw-chiffre\">100 %</span> (<span class=\"kw-def\">ALD</span> 30) si pathologie reconnue.</li>\n</ul>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion de maladie génétique constitutionnelle","detail":"Consultation de génétique : interrogatoire, arbre généalogique ≥ 3 générations, examen clinique, examens orientés.","branches":[{"to":"orientation","label":"Orientation diagnostique","color":"blue"}]},{"id":"orientation","kind":"decision","label":"Une pathologie est-elle suspectée précisément ?","detail":"Selon le phénotype, choisir la stratégie de séquençage la plus rentable.","branches":[{"to":"cible","label":"Oui — gène ou panel ciblé","color":"green"},{"to":"exome","label":"Non — phénotype large","color":"amber"}]},{"id":"cible","kind":"terminal","label":"Séquençage ciblé (gène ou panel)","color":"green","detail":"Indication précise (ex. <em>BRCA1/2</em>, panel cardiomyopathies). Coût faible, délai court, peu de découvertes fortuites. Consentement écrit obligatoire."},{"id":"exome","kind":"decision","label":"Préindication PFMG 2025 retenue en RCP ?","detail":"Validation par réunion de concertation pluridisciplinaire avant adressage à une plateforme SeqOIA / AURAGEN.","branches":[{"to":"wes","label":"Oui — exome (WES)","color":"amber"},{"to":"wgs","label":"Oui — génome (WGS)","color":"red"},{"to":"non","label":"Non retenue","color":"green"}]},{"id":"wes","kind":"terminal","label":"Séquençage d'exome (WES)","color":"amber","detail":"Couvre l'ensemble des régions codantes (~2 % du génome) où siègent ~85 % des variants pathogènes. Trio (cas index + parents) +++ pour interprétation. Découvertes secondaires à anticiper au consentement."},{"id":"wgs","kind":"terminal","label":"Séquençage de génome (WGS)","color":"red","detail":"Lecture du génome entier (codant + non-codant), détection de variants structuraux, intronique profond, régulateurs. Réservé aux échecs d'exome ou indications spécifiques. Volume de données et incidentalomes majeurs."},{"id":"non","kind":"terminal","label":"Réévaluation à distance","color":"green","detail":"Pas d'indication actuelle au séquençage haut débit. Suivi clinique, réévaluation périodique selon évolution du phénotype et des connaissances."}]},"objectifs":[{"id":"46-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la médecine génomique","frequence":1,"contenu":"\n<p>La <span class=\"kw-def\">médecine génomique</span> est une approche médicale qui intègre l'analyse du <strong>génome</strong> (ensemble du matériel <span class=\"kw-etio\">génétique</span> d'un individu, ~3 milliards de paires de bases) dans le diagnostic, le <span class=\"kw-def\">pronostic</span> et la prise en charge thérapeutique des patients.</p>\n<p>Elle repose sur les techniques de <span class=\"kw-def\">séquençage haut débit</span> (<em>Next Generation Sequencing</em>, <strong>NGS</strong>), qui permettent de lire en parallèle des millions de fragments d'ADN, et qui ont rendu accessible en routine le séquençage de gènes, d'exomes (<span class=\"kw-bio\">WES</span>) ou de génomes entiers (<span class=\"kw-bio\">WGS</span>).</p>\n<table>\n  <thead><tr><th>Champ d'application</th><th>Exemples</th></tr></thead>\n  <tbody>\n    <tr><td><strong>Maladies rares constitutionnelles</strong></td><td>Déficience intellectuelle, dysmorphies, maladies métaboliques, cardiomyopathies familiales.</td></tr>\n    <tr><td><strong>Oncogénétique constitutionnelle</strong></td><td>Prédispositions héréditaires aux cancers (<span class=\"kw-etio\">BRCA1/2</span>, <span class=\"kw-etio\">syndrome de Lynch</span>, <span class=\"kw-etio\">Li-Fraumeni</span>).</td></tr>\n    <tr><td><strong>Oncologie somatique</strong></td><td>Caractérisation moléculaire des tumeurs, identification de biomarqueurs pour traitements ciblés.</td></tr>\n    <tr><td><strong>Pharmacogénétique</strong></td><td>Adaptation thérapeutique (<span class=\"kw-etio\">DPD</span>/5-FU, <span class=\"kw-etio\">TPMT</span>/thiopurines, <span class=\"kw-etio\">CYP2C19</span>/<span class=\"kw-ttt\">clopidogrel</span>).</td></tr>\n    <tr><td><strong>Maladies infectieuses</strong></td><td>Séquençage de pathogènes (typage, résistance).</td></tr>\n    <tr><td><strong>Médecine prédictive</strong></td><td>Identification de variants à risque chez des apparentés asymptomatiques.</td></tr>\n  </tbody>\n</table>\n<p>En France, le <strong>Plan France Médecine Génomique 2025</strong> (lancé en 2016) structure l'accès au séquençage très haut débit en pratique clinique, via deux plateformes nationales : <em>SeqOIA</em> et <em>AURAGEN</em>.</p>"},{"id":"46-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d'une maladie génétique","frequence":2,"contenu":"\n<p>Le diagnostic d'une <span class=\"kw-def\">maladie génétique</span> repose sur une démarche structurée combinant clinique, généalogie et examens complémentaires ciblés.</p>\n<table>\n  <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n  <tbody>\n    <tr><td><strong>1. Consultation de <span class=\"kw-etio\">génétique</span></strong></td><td>Médecin généticien (ou spécialiste formé) + <span class=\"kw-def\">conseiller en génétique</span>. Interrogatoire détaillé : antécédents personnels et familiaux, consanguinité, origine géographique.</td></tr>\n    <tr><td><strong>2. <span class=\"kw-def\">Arbre généalogique</span></strong></td><td>Sur <span class=\"kw-chiffre\">≥ 3 générations</span>, symboles standardisés. Identifie le <strong>mode de transmission</strong> (AD, AR, lié à l'X, mitochondrial).</td></tr>\n    <tr><td><strong>3. Examen clinique</strong></td><td><span class=\"kw-clinique\">Dysmorphie</span> faciale et corporelle, anomalies des extrémités, retentissement neurodéveloppemental, atteinte d'organes.</td></tr>\n    <tr><td><strong>4. Examens orientés</strong></td><td><span class=\"kw-imagerie\">Imagerie</span>, <span class=\"kw-bio\">bilan métabolique</span>, <span class=\"kw-bio\">EMG</span>, <span class=\"kw-bio\">biopsie</span> selon le phénotype.</td></tr>\n    <tr><td><strong>5. <span class=\"kw-alerte\">Consentement écrit</span></strong></td><td>Obligatoire avant tout examen <span class=\"kw-etio\">génétique</span>. Information sur objectifs, limites, conséquences familiales, gestion des découvertes secondaires.</td></tr>\n    <tr><td><strong>6. Examen <span class=\"kw-etio\">génétique</span></strong></td><td>Choisi selon l'hypothèse :\n      <ul>\n        <li><strong>Caryotype</strong> : anomalies chromosomiques de nombre (<span class=\"kw-etio\">T21</span>) ou de structure visibles.</li>\n        <li><strong><span class=\"kw-bio\">ACPA</span></strong> (analyse chromosomique sur puce à ADN) : microdélétions / microduplications &lt; 5 Mb. <strong>1<sup>re</sup> intention</strong> dans la déficience intellectuelle inexpliquée.</li>\n        <li><strong><span class=\"kw-bio\">FISH</span></strong> : ciblé sur une région connue.</li>\n        <li><strong>Gène ciblé / panel NGS</strong> : phénotype évocateur d'un gène / d'un groupe de gènes.</li>\n        <li><strong>Exome (<span class=\"kw-bio\">WES</span>) / Génome (<span class=\"kw-bio\">WGS</span>)</strong> : phénotype large, errance diagnostique.</li>\n      </ul>\n    </td></tr>\n    <tr><td><strong>7. Rendu</strong></td><td>En <strong>consultation</strong>, jamais par téléphone. <span class=\"kw-def\">Classification</span> ACMG des variants (classes 1 à 5 : bénin → pathogène).</td></tr>\n    <tr><td><strong>8. Conseil <span class=\"kw-etio\">génétique</span> familial</strong></td><td>Information de la parentèle, <span class=\"kw-def\">dépistage</span> en cascade des apparentés, conseil reproductif (<span class=\"kw-def\">DPN</span>, <span class=\"kw-def\">DPI</span>).</td></tr>\n  </tbody>\n</table>\n<p><strong>Place du diagnostic prénatal :</strong> indications validées en <strong>CPDPN</strong>, après consentement, par choriocentèse (dès 11 SA) ou amniocentèse (dès 15 SA), parfois <span class=\"kw-bio\">NIPT</span> (ADN libre circulant) en 1<sup>re</sup> intention.</p>"},{"id":"46-3","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les conditions de prescription d'un test génétique, les principales indications","frequence":3,"contenu":"\n<p><strong>Conditions légales et réglementaires (loi de bioéthique) :</strong></p>\n<table>\n  <thead><tr><th>Condition</th><th>Détail</th></tr></thead>\n  <tbody>\n    <tr><td><strong>Prescripteur</strong></td><td>Médecin ayant <span class=\"kw-def\">suivi</span> une <strong>formation à la <span class=\"kw-etio\">génétique</span></strong> (décret 2013) : généticien, oncogénéticien, ou spécialiste formé.</td></tr>\n    <tr><td><strong><span class=\"kw-alerte\">Consentement écrit</span></strong></td><td>Daté et signé après <strong>information éclairée</strong> (objectifs, limites, gestion des découvertes secondaires, conséquences familiales). Consentement spécifique pour chaque examen.</td></tr>\n    <tr><td><strong>Information préalable</strong></td><td>En consultation dédiée, avec délai de réflexion.</td></tr>\n    <tr><td><strong>Laboratoire</strong></td><td><strong>Agréé par l'ABM</strong> (Agence de la Biomédecine).</td></tr>\n    <tr><td><strong>Rendu</strong></td><td>En <strong>consultation</strong> par le prescripteur, jamais par téléphone, courrier ou mail.</td></tr>\n    <tr><td><strong>Mineur</strong></td><td>Limité aux pathologies à <strong>expression pédiatrique</strong> pour lesquelles une PEC est disponible. Pas de diagnostic présymptomatique d'affections adultes.</td></tr>\n    <tr><td><strong>Diagnostic présymptomatique</strong></td><td>(<span class=\"kw-etio\">Huntington</span>, <span class=\"kw-etio\">cancers héréditaires</span>…) → <strong>protocole multidisciplinaire</strong> (généticien, psychologue, spécialiste d'organe), délai de réflexion long.</td></tr>\n    <tr><td><strong>Information de la parentèle</strong></td><td>Devoir du patient si maladie grave susceptible de prévention/curation ; le médecin peut informer indirectement via le patient (procédure encadrée).</td></tr>\n    <tr><td><strong>Confidentialité</strong></td><td>Interdiction d'utilisation par assureurs et employeurs (Code des assurances, Code du travail).</td></tr>\n  </tbody>\n</table>\n<p><strong>Principales indications :</strong></p>\n<ul>\n  <li><strong>Diagnostic d'une maladie rare</strong> avec présomption <span class=\"kw-etio\">génétique</span> : déficience intellectuelle inexpliquée, syndromes dysmorphiques, maladies métaboliques, cardiomyopathies / canalopathies familiales, surdité, cécité, maladies neuromusculaires.</li>\n  <li><strong>Oncogénétique constitutionnelle</strong> : <span class=\"kw-etio\">BRCA1/2</span> (sein/ovaire), <span class=\"kw-etio\">syndrome de Lynch</span> (côlon, endomètre), <span class=\"kw-etio\">polypose</span>, <span class=\"kw-etio\">Li-Fraumeni</span>, <span class=\"kw-etio\">NEM</span>, rétinoblastome.</li>\n  <li><strong>Oncologie somatique</strong> : caractérisation moléculaire de la tumeur pour traitement ciblé (<span class=\"kw-etio\">EGFR</span>, <span class=\"kw-etio\">KRAS</span>, <span class=\"kw-etio\">BRAF</span>, fusions <span class=\"kw-etio\">ALK</span>/<span class=\"kw-etio\">ROS1</span>…).</li>\n  <li><strong>Pharmacogénétique</strong> : <span class=\"kw-etio\">DPD</span> avant 5-FU, <span class=\"kw-etio\">TPMT</span> avant thiopurines, <span class=\"kw-etio\">UGT1A1</span> avant irinotécan.</li>\n  <li><strong>Diagnostic prénatal / préimplantatoire</strong> dans le cadre du <strong>CPDPN</strong>, pour affection d'une particulière gravité reconnue incurable.</li>\n  <li><strong><span class=\"kw-def\">Dépistage</span> en cascade</strong> des apparentés d'un cas index porteur d'un variant pathogène.</li>\n</ul>"},{"id":"46-4","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les stratégies de séquençage haut débit et les limites de ces tests","frequence":1,"contenu":"\n<p>Le <span class=\"kw-def\">séquençage haut débit</span> (<strong>NGS</strong>, <em>Next Generation Sequencing</em>) permet la lecture parallèle massive de millions de fragments d'ADN. Plusieurs stratégies se distinguent par leur <strong>périmètre</strong>, leur <strong>coût</strong> et leur <strong>rendement diagnostique</strong>.</p>\n<table>\n  <thead><tr><th>Stratégie</th><th>Périmètre</th><th>Indications principales</th><th>Avantages</th><th>Limites</th></tr></thead>\n  <tbody>\n    <tr>\n      <td><strong>Gène ciblé</strong></td>\n      <td><span class=\"kw-chiffre\">1 g</span>ène</td>\n      <td>Phénotype évocateur d'une pathologie monogénique connue (<span class=\"kw-etio\">mucoviscidose</span> : <em>CFTR</em>).</td>\n      <td>Coût faible, délai court, peu de découvertes fortuites.</td>\n      <td>Pas adapté aux hétérogénéités génétiques.</td>\n    </tr>\n    <tr>\n      <td><strong>Panel de gènes</strong></td>\n      <td>Quelques dizaines à centaines de gènes d'un même groupe phénotypique.</td>\n      <td>Cardiomyopathies, surdité, prédispositions au cancer (panel <span class=\"kw-etio\">BRCA</span>+).</td>\n      <td>Bon rendement, interprétation simplifiée.</td>\n      <td>Manque les gènes nouvellement découverts hors panel.</td>\n    </tr>\n    <tr>\n      <td><strong>Exome (<span class=\"kw-bio\">WES</span>)</strong></td>\n      <td>~<span class=\"kw-chiffre\">2 %</span> du génome (régions codantes des ~20 <span class=\"kw-chiffre\">000 g</span>ènes).</td>\n      <td>Phénotype large, errance diagnostique, déficience intellectuelle. Idéalement <strong>en trio</strong> (cas index + parents).</td>\n      <td>Couvre ~<span class=\"kw-chiffre\">85 %</span> des variants pathogènes connus.</td>\n      <td>Manque variants introniques profonds, structuraux, régions non couvertes ; <strong>découvertes secondaires</strong>.</td>\n    </tr>\n    <tr>\n      <td><strong>Génome (<span class=\"kw-bio\">WGS</span>)</strong></td>\n      <td>Quasi-totalité du génome (codant + non-codant + structurel).</td>\n      <td>Échec d'exome, suspicion de variants structuraux ou de régions non codantes.</td>\n      <td>Détection de variants structuraux, ADN mitochondrial, couverture homogène.</td>\n      <td>Volume de données massif, coût élevé, <strong>incidentalomes</strong>, interprétation complexe.</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-bio\">RNA-seq</span></strong></td>\n      <td>Transcriptome.</td>\n      <td>Complément du WES/WGS pour caractériser l'impact fonctionnel d'un variant d'épissage.</td>\n      <td>Met en évidence des variants régulateurs.</td>\n      <td>Tissu-spécifique, accès parfois difficile au tissu pertinent.</td>\n    </tr>\n  </tbody>\n</table>\n<p><strong>Limites communes au NGS :</strong></p>\n<ul>\n  <li><strong>Variants de signification incertaine (<span class=\"kw-def\">VUS</span>)</strong> : ne permettent <span class=\"kw-alerte\">aucune décision thérapeutique</span> ; <span class=\"kw-def\">réévaluation</span> périodique nécessaire.</li>\n  <li><strong>Faux négatifs</strong> : régions mal couvertes, expansions de triplets (<span class=\"kw-etio\">X fragile</span>, <span class=\"kw-etio\">Huntington</span>) non détectées par NGS standard, variants structuraux mal vus par exome.</li>\n  <li><strong>Faux positifs</strong> : nécessitent confirmation par méthode orthogonale (Sanger).</li>\n  <li><strong>Découvertes secondaires / incidentalomes</strong> : variants pathogènes sans lien avec l'indication initiale → choix du patient recueilli au consentement, discussion en <span class=\"kw-def\">RCP</span>.</li>\n  <li><strong>Interprétation</strong> dépendante de la qualité des bases de données et de l'expertise du laboratoire.</li>\n  <li><strong>Stockage et confidentialité</strong> de données massives, durables, partageables (problématique éthique et juridique).</li>\n  <li><strong>Coût</strong> et accessibilité encore inégaux ; en France, encadrement par le <strong>Plan France Médecine Génomique 2025</strong> (plateformes <em>SeqOIA</em> et <em>AURAGEN</em>).</li>\n  <li><strong>Délai de rendu</strong> (plusieurs mois) incompatible avec certaines situations aiguës.</li>\n</ul>"}],"astuces":[{"type":"tip","titre":"Mnémo « 4 piliers » du test génétique","contenu":"<p><strong>C-A-R-R</strong> : <strong>C</strong>onsentement écrit · <strong>A</strong>rbre généalogique (<span class=\"kw-chiffre\">≥ 3 g</span>énérations) · <strong>R</strong>endu en consultation · <strong>R</strong>elais à la parentèle. Les 4 incontournables qui tombent en QCM dès qu'on parle de prescription d'un test <span class=\"kw-etio\">génétique</span>.</p>"},{"type":"info","titre":"Astuce PU — choisir entre panel, exome et génome","contenu":"<p>Logique simple à retenir : <strong>panel</strong> si le phénotype pointe vers un groupe de gènes connus (cardiomyopathies, BRCA+) ; <strong>exome (WES)</strong> en cas de phénotype large ou d'errance diagnostique (déficience intellectuelle), idéalement <em>en trio</em> avec les parents ; <strong>génome (WGS)</strong> en 3<sup>e</sup> ligne après échec d'exome ou suspicion de variants structuraux. Le PFMG 2025 (SeqOIA / AURAGEN) ne séquence qu'après validation en <span class=\"kw-def\">RCP</span>.</p>"},{"type":"warn","titre":"Piège classique — le VUS","contenu":"<p>Un <strong>variant de signification incertaine (VUS, <span class=\"kw-chiffre\">classe 3</span> ACMG)</strong> n'est <span class=\"kw-alerte\">jamais</span> un argument pour modifier la prise en charge (pas de <span class=\"kw-ttt\">chirurgie</span> prophylactique, pas de <span class=\"kw-clinique\">DPN</span>). Il doit être <strong>réévalué périodiquement</strong> à la lumière des bases de données. Toute question d'EDN qui propose d'agir sur un VUS est fausse.</p>"},{"type":"danger","titre":"Drapeau rouge — découverte secondaire (incidentalome)","contenu":"<p>Un séquençage d'exome ou de génome peut révéler un variant pathogène <strong>sans lien</strong> avec l'indication initiale (ex. mutation <em>BRCA1</em> trouvée lors d'un exome pour déficience intellectuelle). Le rendu est conditionné par : (1) le <strong>choix du patient recueilli au consentement initial</strong>, (2) une discussion en <strong><span class=\"kw-def\">RCP</span> de <span class=\"kw-etio\">génétique</span> constitutionnelle</strong>, (3) un caractère <strong>actionnable</strong> (prévention/traitement disponibles).</p>"},{"type":"tip","titre":"Discriminant clé — ACPA vs caryotype","contenu":"<p>Devant une <strong>déficience intellectuelle inexpliquée</strong>, l'examen de <strong>1<sup>re</sup> intention est l'ACPA</strong> (analyse chromosomique sur puce à ADN), pas le caryotype standard. L'ACPA détecte les microdélétions / microduplications &lt; 5 Mb invisibles au caryotype, avec un rendement diagnostique de ~<span class=\"kw-chiffre\">15-20 %</span>.</p>"}],"liensGlobaux":[{"href":"https://livret.uness.fr/lisa/D%C3%A9pistage_pr%C3%A9natal_de_la_trisomie_21_SD-307","label":"dépistage prénatal de la trisomie 21"}],"cards":[{"i":"2b061ca4a1aa","n":46,"o":"46-1","u":"Définition","t":"Connaître la définition de la médecine génomique","q":"Quels sont les principaux champs d'application de la médecine génomique ?","a":"<ul><li>Les <strong>maladies rares constitutionnelles</strong> (ex: déficience intellectuelle, cardiomyopathies).</li><li>L'<strong>oncogénétique constitutionnelle</strong> (ex: prédispositions aux cancers comme BRCA1/2).</li><li>L'<strong>oncologie somatique</strong> (caractérisation moléculaire des tumeurs, biomarqueurs).</li><li>La <strong>pharmacogénétique</strong> (adaptation thérapeutique selon le profil génétique, ex: DPD/5-FU).</li><li>Les <strong>maladies infectieuses</strong> (typage, résistance des pathogènes).</li><li>La <strong>médecine prédictive</strong> (identification de variants à risque chez les apparentés asymptomatiques).</li></ul>"},{"i":"54190daa2f49","n":46,"o":"46-1","u":"Définition","t":"Connaître la définition de la médecine génomique","q":"Quel est le cadre national en France pour la médecine génomique ?","a":"<p>En France, le <strong>Plan France Médecine Génomique 2025</strong> (lancé en 2016) structure l'accès au séquençage très haut débit en pratique clinique, via deux plateformes nationales : <strong>SeqOIA</strong> et <strong>AURAGEN</strong>.</p>"},{"i":"9f63e659294d","n":46,"o":"46-1","u":"Définition","t":"Connaître la définition de la médecine génomique","q":"Quelle est la définition de la médecine génomique ?","a":"<p>La médecine génomique est une approche médicale qui intègre l'analyse du <strong>génome</strong> (l'ensemble du matériel génétique d'un individu), dans le <strong>diagnostic</strong>, le <strong>pronostic</strong> et la <strong>prise en charge thérapeutique</strong> des patients.</p>"},{"i":"cdd8cca07040","n":46,"o":"46-1","u":"Définition","t":"Connaître la définition de la médecine génomique","q":"Sur quelles techniques principales repose la médecine génomique ?","a":"<p>La médecine génomique repose principalement sur les techniques de <strong>séquençage haut débit</strong> (Next Generation Sequencing, <strong>NGS</strong>), qui permettent de lire des millions de fragments d'ADN en parallèle. Ces techniques rendent accessible le séquençage de gènes, d'exomes (<strong>WES</strong>) ou de génomes entiers (<strong>WGS</strong>).</p>"},{"i":"946da1053287","n":46,"o":"46-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'une maladie génétique","q":"Quelles sont les étapes initiales après la consultation de génétique pour établir le diagnostic d'une maladie génétique ?","a":"<ul><li>La construction d'un <strong>arbre généalogique sur au moins 3 générations</strong>, utilisant des symboles standardisés, permet d'identifier le mode de transmission (autosomique dominant, autosomique récessif, lié à l'X, mitochondrial).</li><li>Un <strong>examen clinique détaillé</strong> recherche des signes spécifiques comme une dysmorphie faciale ou corporelle, des anomalies des extrémités, un retentissement neurodéveloppemental ou des atteintes d'organes spécifiques.</li><li>Des <strong>examens orientés</strong> (imagerie, bilan métabolique, EMG, biopsie) sont réalisés selon le phénotype observé.</li></ul>"},{"i":"aa46c01a986b","n":46,"o":"46-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'une maladie génétique","q":"Quel est le rôle du consentement écrit et des examens génétiques dans le diagnostic d'une maladie génétique ?","a":"<p>Un <strong>consentement écrit est obligatoire</strong> avant tout examen génétique, informant le patient sur les objectifs, limites, conséquences familiales et la gestion des découvertes secondaires. L'<strong>examen génétique est choisi selon l'hypothèse clinique</strong> et peut inclure un <strong>caryotype</strong> (anomalies chromosomiques visibles), une <strong>ACPA</strong> (microdélétions/microduplications), une <strong>FISH</strong> (région ciblée), un <strong>gène ciblé/panel NGS</strong> (phénotype évocateur) ou un <strong>WES/WGS</strong> (phénotype large, errance diagnostique).</p>"},{"i":"c8677d771061","n":46,"o":"46-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'une maladie génétique","q":"Quelle est l'approche structurée pour le diagnostic d'une maladie génétique ?","a":"<p>Le diagnostic d'une maladie génétique repose sur une démarche structurée combinant des éléments <strong>cliniques</strong>, l'analyse <strong>généalogique</strong> et des <strong>examens complémentaires ciblés</strong>.</p>"},{"i":"d06cdafa6822","n":46,"o":"46-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'une maladie génétique","q":"Comment les résultats des examens génétiques sont-ils communiqués et quel rôle joue le conseil génétique familial ?","a":"<p>Le rendu des résultats doit se faire <strong>en consultation</strong> et jamais par téléphone. Les variants sont classifiés selon l'<strong>ACMG</strong> (classes 1 à 5, de bénin à pathogène). Le <strong>conseil génétique familial</strong> permet l'information de la parentèle, le dépistage en cascade des apparentés et un conseil reproductif, incluant le diagnostic prénatal (DPN) et le diagnostic préimplantatoire (DPI).</p>"}]};